import dspy
from dspy.primitives.prediction import Prediction
from tests.mock_interpreter import MockInterpreter


def make_mock_predictor(responses):
    class MockPredictor:
        def __init__(self):
            self.idx = 0

        def _next_response(self):
            result = responses[self.idx % len(responses)]
            self.idx += 1
            return Prediction(**result)

        def __call__(self, **kwargs):
            return self._next_response()

        async def acall(self, **kwargs):
            return self._next_response()

    return MockPredictor()


interpreter = MockInterpreter(responses=["exploring...", "still exploring...", "more exploring..."])
rlm = dspy.RLM("query -> answer", max_iterations=3, interpreter=interpreter)
rlm.generate_action = make_mock_predictor(
    [
        {"reasoning": "Explore 1", "code": "print('exploring')"},
        {"reasoning": "Explore 2", "code": "print('exploring')"},
        {"reasoning": "Explore 3", "code": "print('exploring')"},
    ]
)
rlm.extract = make_mock_predictor([{"answer": "extracted_answer"}])

result = rlm.forward(query="test")

print("answer:", result.answer)
print("final reasoning:", result.final_reasoning)
print("trajectory:", result.trajectory)

assert result.answer == "extracted_answer"
assert result.final_reasoning == "Extract forced final output"
assert len(result.trajectory) == 3
assert result.trajectory[-1]["output"] == "more exploring..."
